Rules.InvariantScript:
If(!varCargado,
    Concurrent(
        ClearCollect(colPersonal, tblPersonal),
        If(IsError(ClearCollect(colIngresos, tblIngresos)), false),
        ClearCollect(colHistorial, tblHistorial),
        ClearCollect(colDonantes, tblDonantes)
    );
    Set(varYo, LookUp(colPersonal, Lower(Trim(Correo)) = Lower(User().Email) && Activo = "Sí"));
    Set(varArea, If(IsBlank(varYo), "Sin acceso", varYo.Area));
    Set(varCargado, true)
);
If(IsEmpty(colFicha), ClearCollect(colFicha, tblFichaDescarte));
If(IsBlank(varTema), Set(varTema, "claro"));
If(IsBlank(varVista), Set(varVista, "Estantería"));
If(IsBlank(varAbierto), Set(varAbierto, 0); Set(varPrev, 0));
Set(varAnimando, false);
If(IsBlank(varResumen), Set(varResumen, ParseJSON("{}")); ClearCollect(colSerie, FirstN(Table({i: 0, d: "", n: 0}), 0)));
If(IsBlank(varAgendaLeida), Set(varAgendaLeida, false));
If(IsEmpty(colMes), ClearCollect(colMes, FirstN(Table({i: 0, n: 0}), 0)); ClearCollect(colMesAnt, FirstN(Table({i: 0, n: 0}), 0)));
ClearCollect(colServ,
    {n: 7, rom: "I", lo: "Contador", nm: "Contador de personas", est: "", tipo: "neu", kpi: "—", kpil: "POR RONDA", msg: ""},
    {n: 1, rom: "II", lo: "Ingresos", nm: "Ingreso de material", est: "", tipo: "neu", kpi: Text(CountRows(Filter(colIngresos, Etapa = "En PPTT" || Etapa = "Recibido en PPTT" || Etapa = "Catalogado" || Etapa = "Marbete impreso")), "#,0", "es-CL"), kpil: "EN PPTT", msg: ""},
    {n: 2, rom: "III", lo: "Marbetes", nm: "Generador de marbetes", est: "", tipo: "neu", kpi: "—", kpil: "POR CÓDIGO", msg: ""},
    {n: 3, rom: "IV", lo: "Morosos", nm: "Cobranza de morosos", est: "", tipo: "neg", kpi: If(!IsBlank(Text(varResumen.fecha)), Text(Value(varResumen.morosos), "#,0", "es-CL"), "—"), kpil: "USUARIOS", msg: ""},
    {n: 4, rom: "V", lo: "Descarte", nm: "Descarte de títulos", est: "", tipo: "neu", kpi: Text(CountRows(colFicha), "#,0", "es-CL"), kpil: "EN LA FICHA", msg: ""},
    {n: 5, rom: "VI", lo: "Préstamos", nm: "Préstamos y devoluciones", est: "", tipo: "neu", kpi: If(!IsBlank(Text(varResumen.fecha)), Text(Value(varResumen.hoy), "#,0", "es-CL"), "—"), kpil: "ÚLTIMO DÍA", msg: ""},
    {n: 6, rom: "VII", lo: "Inventario", nm: "Inventario y revisión", est: "", tipo: "neu", kpi: "—", kpil: "POR ESTANTE", msg: ""}
);
ClearCollect(colAlertas,
    {k: 1, p: 3, n: CountRows(Filter(colIngresos, Etapa = "En PPTT" && IsBlank('Estado PPTT'))), txt: "títulos en PPTT sin estado", sub: "II · Ingreso de material · tblIngresos (etapa En PPTT, sin Estado PPTT)", area: "PPTT"},
    {k: 2, p: 3, n: If(!IsBlank(Text(varResumen.fecha)), Value(varResumen.mor30), 0), txt: "usuarios con más de 30 días de atraso", sub: "IV · Morosos · FOLIO (flujo FolioResumenInicio)", area: "BIBLIOTECA"},
    {k: 3, p: 2, n: CountRows(Filter(colIngresos, Etapa = "Registrado en Biblioteca")), txt: "títulos sin recibir en ADQ", sub: "II · Ingreso de material · tblIngresos", area: "ADQ"},
    {k: 4, p: 2, n: CountRows(Filter(colIngresos, Etapa = "Devuelto a Biblioteca")), txt: "títulos devueltos por recibir", sub: "II · Ingreso de material · tblIngresos", area: "BIBLIOTECA"},
    {k: 5, p: 1, n: CountRows(Filter(colFicha, IsBlank('Decisión Final Descarte SI/NO'))), txt: "libros sin decisión final de descarte", sub: "V · Descarte · Ficha de descarte", area: "BIBLIOTECA"}
);
RemoveIf(colAlertas, n = 0);
IfError(ClearCollect(colNotas, Filter(tblNotas, Lower(Correo) = Lower(User().Email))), false)

If(IsBlank(Text(varResumen.fecha)),
    Set(varResumenTxt, IfError(Text('FolioResumenInicio'.Run().datos), ""));
    Set(varResumen, ParseJSON(If(IsBlank(varResumenTxt), "{}", varResumenTxt)));
    With({s: Split(Text(varResumen.serie), ";")},
        ClearCollect(colSerie,
            ForAll(Sequence(CountRows(s)),
                With({p: Split(Index(s, Value).Value, "|")},
                    {i: Value, d: First(p).Value, n: Value(Last(p).Value)}
                )
            )
        )
    )
);
With({a: Split(Text(varResumen.mes), ";"), b: Split(Text(varResumen.mesAnt), ";")},
    ClearCollect(colMes, ForAll(Filter(Sequence(CountRows(a)), !IsBlank(Index(a, Value).Value)), {i: Value, n: Value(Index(a, Value).Value)}));
    ClearCollect(colMesAnt, ForAll(Filter(Sequence(CountRows(b)), !IsBlank(Index(b, Value).Value)), {i: Value, n: Value(Index(b, Value).Value)})));
ClearCollect(colServ,
    {n: 7, rom: "I", lo: "Contador", nm: "Contador de personas", est: "", tipo: "neu", kpi: "—", kpil: "POR RONDA", msg: ""},
    {n: 1, rom: "II", lo: "Ingresos", nm: "Ingreso de material", est: "", tipo: "neu", kpi: Text(CountRows(Filter(colIngresos, Etapa = "En PPTT" || Etapa = "Recibido en PPTT" || Etapa = "Catalogado" || Etapa = "Marbete impreso")), "#,0", "es-CL"), kpil: "EN PPTT", msg: ""},
    {n: 2, rom: "III", lo: "Marbetes", nm: "Generador de marbetes", est: "", tipo: "neu", kpi: "—", kpil: "POR CÓDIGO", msg: ""},
    {n: 3, rom: "IV", lo: "Morosos", nm: "Cobranza de morosos", est: "", tipo: "neg", kpi: If(!IsBlank(Text(varResumen.fecha)), Text(Value(varResumen.morosos), "#,0", "es-CL"), "—"), kpil: "USUARIOS", msg: ""},
    {n: 4, rom: "V", lo: "Descarte", nm: "Descarte de títulos", est: "", tipo: "neu", kpi: Text(CountRows(colFicha), "#,0", "es-CL"), kpil: "EN LA FICHA", msg: ""},
    {n: 5, rom: "VI", lo: "Préstamos", nm: "Préstamos y devoluciones", est: "", tipo: "neu", kpi: If(!IsBlank(Text(varResumen.fecha)), Text(Value(varResumen.hoy), "#,0", "es-CL"), "—"), kpil: "ÚLTIMO DÍA", msg: ""},
    {n: 6, rom: "VII", lo: "Inventario", nm: "Inventario y revisión", est: "", tipo: "neu", kpi: "—", kpil: "POR ESTANTE", msg: ""}
);
ClearCollect(colAlertas,
    {k: 1, p: 3, n: CountRows(Filter(colIngresos, Etapa = "En PPTT" && IsBlank('Estado PPTT'))), txt: "títulos en PPTT sin estado", sub: "II · Ingreso de material · tblIngresos (etapa En PPTT, sin Estado PPTT)", area: "PPTT"},
    {k: 2, p: 3, n: If(!IsBlank(Text(varResumen.fecha)), Value(varResumen.mor30), 0), txt: "usuarios con más de 30 días de atraso", sub: "IV · Morosos · FOLIO (flujo FolioResumenInicio)", area: "BIBLIOTECA"},
    {k: 3, p: 2, n: CountRows(Filter(colIngresos, Etapa = "Registrado en Biblioteca")), txt: "títulos sin recibir en ADQ", sub: "II · Ingreso de material · tblIngresos", area: "ADQ"},
    {k: 4, p: 2, n: CountRows(Filter(colIngresos, Etapa = "Devuelto a Biblioteca")), txt: "títulos devueltos por recibir", sub: "II · Ingreso de material · tblIngresos", area: "BIBLIOTECA"},
    {k: 5, p: 1, n: CountRows(Filter(colFicha, IsBlank('Decisión Final Descarte SI/NO'))), txt: "libros sin decisión final de descarte", sub: "V · Descarte · Ficha de descarte", area: "BIBLIOTECA"}
);
RemoveIf(colAlertas, n = 0)

Set(varCamInicio, First(Self.Barcodes).Value); Reset(txtBuscarInicio); With({q: Trim(First(Self.Barcodes).Value)},
    If(Len(q) < 2,
        Notify("Escriba al menos 2 caracteres.", NotificationType.Information),
        With({ing: First(Filter(colIngresos, Text(Correlativo) = q || Lower(q) in Lower(Titulo) || Lower(q) in Lower(Autor) || q = Text('Numero inventario')))},
            If(!IsBlank(ing),
                Set(varSel, ing); Navigate(scrIngDetalle, ScreenTransition.Fade),
                q in colFicha.'Codigo de Barra',
                Notify("El código " & q & " ya está en la Ficha de Descarte.", NotificationType.Information),
                Set(varCodEj, q); Set(varEj, ParseJSON("{}")); Navigate(ConsultarEjemplar, ScreenTransition.Fade)
            )
        )
    )
)

With({q: Trim(txtBuscarInicio.Text)},
    If(Len(q) < 2,
        Notify("Escriba al menos 2 caracteres.", NotificationType.Information),
        With({ing: First(Filter(colIngresos, Text(Correlativo) = q || Lower(q) in Lower(Titulo) || Lower(q) in Lower(Autor) || q = Text('Numero inventario')))},
            If(!IsBlank(ing),
                Set(varSel, ing); Navigate(scrIngDetalle, ScreenTransition.Fade),
                q in colFicha.'Codigo de Barra',
                Notify("El código " & q & " ya está en la Ficha de Descarte.", NotificationType.Information),
                Set(varCodEj, q); Set(varEj, ParseJSON("{}")); Navigate(ConsultarEjemplar, ScreenTransition.Fade)
            )
        )
    )
)

With({q: Trim(txtBuscarInicio.Text)},
    If(Len(q) < 2,
        Notify("Escriba al menos 2 caracteres.", NotificationType.Information),
        With({ing: First(Filter(colIngresos, Text(Correlativo) = q || Lower(q) in Lower(Titulo) || Lower(q) in Lower(Autor) || q = Text('Numero inventario')))},
            If(!IsBlank(ing),
                Set(varSel, ing); Navigate(scrIngDetalle, ScreenTransition.Fade),
                q in colFicha.'Codigo de Barra',
                Notify("El código " & q & " ya está en la Ficha de Descarte.", NotificationType.Information),
                Set(varCodEj, q); Set(varEj, ParseJSON("{}")); Navigate(ConsultarEjemplar, ScreenTransition.Fade)
            )
        )
    )
)
